/* =====================================================================
   Healthcare Insurance Analysis — SQL tasks  (MySQL 8.0+)
   Run:  mysql -u root -p < healthcare_insurance.sql
   Raw data from Hospitalisation details.csv and Medical Examinations.csv
   is embedded below exactly as delivered (including '?' placeholders).
   ===================================================================== */

DROP DATABASE IF EXISTS healthcare;
CREATE DATABASE healthcare;
USE healthcare;

CREATE TABLE hospitalization_details (
    customer_id   VARCHAR(20),
    year          VARCHAR(4),
    month         VARCHAR(3),
    date          VARCHAR(2),
    children      INT,
    charges       DECIMAL(10,2),
    hospital_tier VARCHAR(10),
    city_tier     VARCHAR(10),
    state_id      VARCHAR(10)
);

CREATE TABLE medical_examinations (
    customer_id               VARCHAR(20),
    bmi                       DECIMAL(5,2),
    hba1c                     DECIMAL(4,2),
    heart_issues              VARCHAR(5),
    any_transplants           VARCHAR(5),
    cancer_history            VARCHAR(5),
    number_of_major_surgeries VARCHAR(20),
    smoker                    VARCHAR(5)
);

