/* ---------------------------------------------------------------------
   Task 1a : the column that links both tables is customer_id.
   Task 1b : remove null / '?' / duplicate keys, then add PRIMARY KEYs.
   --------------------------------------------------------------------- */
SET SQL_SAFE_UPDATES = 0;

-- rows with a trivial '?' anywhere carry no reliable information
DELETE FROM hospitalization_details
WHERE customer_id IS NULL OR '?' IN (customer_id, year, month, date, hospital_tier, city_tier, state_id);

DELETE FROM medical_examinations
WHERE customer_id IS NULL OR '?' IN (customer_id, heart_issues, any_transplants, cancer_history, number_of_major_surgeries, smoker);

-- safeguard: drop any customer_id that is still duplicated (we cannot tell which copy is right).
-- The extra derived-table level avoids MySQL error 1093 (target table used in sub-query).
DELETE FROM hospitalization_details
WHERE customer_id IN (SELECT customer_id FROM (
        SELECT customer_id FROM hospitalization_details GROUP BY customer_id HAVING COUNT(*) > 1) AS dup);

ALTER TABLE hospitalization_details MODIFY customer_id VARCHAR(20) NOT NULL, ADD PRIMARY KEY (customer_id);
ALTER TABLE medical_examinations    MODIFY customer_id VARCHAR(20) NOT NULL, ADD PRIMARY KEY (customer_id);

-- Merged view used by the analysis queries
CREATE OR REPLACE VIEW patient_details AS
SELECT h.customer_id,
       STR_TO_DATE(CONCAT(h.year, '-', h.month, '-', h.date), '%Y-%b-%d')                AS date_of_birth,
       TIMESTAMPDIFF(YEAR, STR_TO_DATE(CONCAT(h.year, '-', h.month, '-', h.date), '%Y-%b-%d'), CURDATE()) AS age,
       h.children, h.charges, h.hospital_tier, h.city_tier, h.state_id,
       m.bmi, m.hba1c, m.heart_issues, m.any_transplants, m.cancer_history,
       CASE WHEN m.number_of_major_surgeries = 'No major surgery' THEN 0
            ELSE CAST(m.number_of_major_surgeries AS UNSIGNED) END                         AS major_surgeries,
       m.smoker
FROM hospitalization_details h
INNER JOIN medical_examinations m ON m.customer_id = h.customer_id;

SELECT COUNT(*) AS merged_rows FROM patient_details;


/* Task 2 : diabetic (HbA1c > 6.5) patients with heart problems —
            average age, dependent children, BMI and hospitalization cost */
SELECT COUNT(*)                AS patients,
       ROUND(AVG(age), 1)      AS avg_age,
       ROUND(AVG(children), 2) AS avg_children,
       ROUND(AVG(bmi), 2)      AS avg_bmi,
       ROUND(AVG(charges), 2)  AS avg_hospitalization_cost
FROM patient_details
WHERE hba1c > 6.5 AND heart_issues = 'yes';


/* Task 3 : average hospitalization cost for each hospital tier and each city tier */
SELECT hospital_tier, city_tier,
       COUNT(*) AS patients, ROUND(AVG(charges), 2) AS avg_cost
FROM patient_details
GROUP BY hospital_tier, city_tier
ORDER BY hospital_tier, city_tier;

-- separately per hospital tier / per city tier
SELECT hospital_tier, ROUND(AVG(charges), 2) AS avg_cost FROM patient_details GROUP BY hospital_tier ORDER BY hospital_tier;
SELECT city_tier,     ROUND(AVG(charges), 2) AS avg_cost FROM patient_details GROUP BY city_tier     ORDER BY city_tier;


/* Task 4 : people who have had major surgery and have a history of cancer */
SELECT COUNT(*) AS surgery_and_cancer_history
FROM patient_details
WHERE major_surgeries > 0 AND cancer_history = 'Yes';


/* Task 5 : number of tier-1 hospital records in each state */
SELECT state_id, COUNT(*) AS tier1_hospitals
FROM hospitalization_details
WHERE hospital_tier = 'tier - 1'
GROUP BY state_id
ORDER BY tier1_hospitals DESC;
